// tools/fw-bundler/tests/standalone.integration.test.js
//
// Golden compare for the `standalone` subcommand — byte match against the
// committed golden (fw extracted from git history at the MANIFEST's
// captureSha — proven byte-identical to the fw original's output on that
// input before the originals were removed; see __fixtures__/golden/README.md).
//
// Legs: byte-identical emitted ESM (copy vs committed golden — generated in a
// child process outside coverage, see generateOutOfCoverage), re-import
// smoke on both, byte-idempotence, and a fixture build (dependency edge +
// minify path). Every leg but the golden compare runs in-process, so the
// generator stays exercised under coverage.
//
// STAMP-FREE OUTPUT (BL-697): the generator no longer emits a
// `// Built: <ISO>` banner, so the `normBuilt` normalizer that used to excuse
// it is gone — the golden and idempotence compares are RAW, and an absence
// assertion pins the banner's removal. A normalizer that outlives its subject
// silently excuses a resurrected stamp.

import { describe, test, expect, beforeEach, afterAll } from 'bun:test';
import { existsSync, rmSync, mkdirSync, readFileSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { pathToFileURL } from 'node:url';

import { generateStandalone as genCopy } from '../src/standalone/index.js';
import { extractFwAt, readManifest, goldenPath, readGolden } from './golden-fw.js';

const ROOT = resolve(import.meta.dir, '..', '..', '..');
const FW_ROOT = join(ROOT, 'packages', 'front', 'fw');
const FIX = join(import.meta.dir, '__fixtures__', 'mini-fw');
const OUT = join(import.meta.dir, '__out__');

// A small, dependency-free fw module that both tools can inline cleanly.
const FW_MODULE = 'hex';

function cleanOut() {
    rmSync(OUT, { recursive: true, force: true });
    rmSync(join(FIX, 'dist'), { recursive: true, force: true });
}

async function importFresh(file) {
    return import(pathToFileURL(file).href + `?t=${Date.now()}_${Math.random()}`);
}

beforeEach(() => { cleanOut(); mkdirSync(OUT, { recursive: true }); });
afterAll(cleanOut);

// Run the generator in a plain child `bun` (BL-1223): factories are serialized
// with `Function.prototype.toString`, and `bun test --coverage` makes Bun serve
// an uncompacted transpile, so an in-process run would emit coverage-mode
// bytes. The compare itself stays RAW, in the parent.
const RUNNER = join(import.meta.dir, 'standalone-golden-runner.js');

function generateOutOfCoverage(moduleName, out, pkg) {
    const env = Object.fromEntries(
        Object.entries(process.env).filter(([k]) => !/coverage/i.test(k)),
    );
    const r = Bun.spawnSync([process.execPath, RUNNER, moduleName, out, pkg], {
        cwd: import.meta.dir, env, stdout: 'pipe', stderr: 'pipe',
    });
    if (r.exitCode !== 0) {
        throw new Error(`standalone golden runner exited ${r.exitCode}: ${r.stderr.toString()}`);
    }
    return JSON.parse(r.stdout.toString().trim());
}

describe('standalone — byte-identical vs the committed golden (frozen fw@captureSha)', () => {
    test(`emitted ESM for "${FW_MODULE}" is RAW-byte-identical and carries no build stamp`, () => {
        const manifest = readManifest();
        const cPath = join(OUT, 'copy.js');

        const cRes = generateOutOfCoverage(FW_MODULE, cPath, extractFwAt(manifest.captureSha));

        expect(manifest.standaloneModule).toBe(FW_MODULE);
        expect(cRes.moduleCount).toBe(manifest.standaloneModuleCount);

        const c = readFileSync(cPath, 'utf8');
        // BL-697: the source-comment header is purely source-derived now.
        expect(c).not.toContain('// Built:');
        expect(c).toContain('// Generated by @awacloud/fw standalone-factory generator');
        expect(c).toBe(readGolden(`${FW_MODULE}.standalone.js`).toString('utf8'));
    });

    test('re-import smoke passes on both the golden and the copy output', async () => {
        const cPath = join(OUT, 'copy.js');
        await genCopy(FW_MODULE, { out: cPath, pkg: extractFwAt(readManifest().captureSha) });

        const g = await importFresh(goldenPath(`${FW_MODULE}.standalone.js`));
        const c = await importFresh(cPath);
        expect(typeof g.default).toBe(typeof c.default);
        expect(Object.keys(c.default ?? {})).toEqual(Object.keys(g.default ?? {}));
    });

    test('byte-idempotence: running the copy twice yields RAW-identical ESM (no normalizer)', async () => {
        const p1 = join(OUT, 'a.js');
        const p2 = join(OUT, 'b.js');
        await genCopy(FW_MODULE, { out: p1, pkg: FW_ROOT });
        await genCopy(FW_MODULE, { out: p2, pkg: FW_ROOT });
        const t1 = readFileSync(p1, 'utf8');
        expect(t1).toBe(readFileSync(p2, 'utf8'));
        // Non-vacuity: real output, and no stamp excused by the compare.
        expect(t1.length).toBeGreaterThan(100);
        expect(t1).not.toContain('// Built:');
    });
});

describe('standalone — fixture (dependency edge + minify path)', () => {
    test('resolves the transitive graph and re-imports (beta → alpha)', async () => {
        const out = join(OUT, 'beta.js');
        const res = await genCopy('beta', { out, pkg: FIX });
        expect(res.modules).toEqual(['alpha', 'beta']);

        const mod = await importFresh(out);
        expect(mod.default.b).toBe(2);
        expect(mod.default.base.a).toBe(1);
    });

    test('--min path produces a smaller, importable bundle', async () => {
        const plain = join(OUT, 'alpha.js');
        const min = join(OUT, 'alpha.min.js');
        const pr = await genCopy('alpha', { out: plain, pkg: FIX });
        const mr = await genCopy('alpha', { out: min, min: true, pkg: FIX });
        expect(mr.minified).toBe(true);
        expect(mr.bytes).toBeLessThanOrEqual(pr.bytes);
        // BL-698 (debugId half): the minify site pins `sourcemap: 'none'`, so
        // Bun's path-derived trailer never reaches the emitted bytes.
        expect(readFileSync(min, 'utf8')).not.toContain('//# debugId=');
        const mod = await importFresh(min);
        expect(mod.default.a).toBe(1);
    });

    test('--classic attaches the module to a global endpoint', async () => {
        const out = join(OUT, 'alpha.classic.js');
        const res = await genCopy('alpha', { out, classic: true, endpoint: 'myAlpha', pkg: FIX });
        expect(res.endpoint).toBe('myAlpha');
        const text = readFileSync(out, 'utf8');
        expect(text).toContain('globalThis.myAlpha');
    });

    test('unknown module rejects', async () => {
        await expect(genCopy('does_not_exist', { out: join(OUT, 'x.js'), pkg: FIX }))
            .rejects.toThrow(/unknown module/);
    });
});
